import logging

from concurrent.futures import ThreadPoolExecutor
from typing import Callable, Coroutine, Type

from dataiku.llm.python import BaseRerankingModel
from dataiku.llm.python.processing.base_processor import BaseProcessor
from dataiku.llm.python.types import RerankingResponse, ProcessSingleRerankingCommand, SingleRerankingResponse
from dataikuapi.dss.llm import DSSLLMRerankingResponse

logger = logging.getLogger(__name__)

class RerankingProcessor(BaseProcessor[BaseRerankingModel, ProcessSingleRerankingCommand, SingleRerankingResponse]):
    def __init__(self, clazz: Type[BaseRerankingModel], executor: ThreadPoolExecutor, config: dict, pluginConfig: dict, trace_name: str):
        super().__init__(clazz=clazz, executor=executor, config=config, pluginConfig=pluginConfig, trace_name=trace_name)

    def get_inference_params(self, command: ProcessSingleRerankingCommand) -> dict:
        query_parts = command.get("queryParts", None)
        if query_parts is None:
            raise Exception(f"'queryParts' missing from command {command}")
        elif len(query_parts) == 0:
            raise Exception(f"'queryParts' is empty in command {command}")
        return {
            "query" : {"queryParts": query_parts, "documents": command.get("documents", [])},
            "settings": command.get("settings", None),
        }

    def get_async_inference_func(self) -> Callable[..., Coroutine]:
        return self._instance.aprocess

    def get_sync_inference_func(self) -> Callable:
        return self._instance.process

    def parse_raw_response(self, raw_response: RerankingResponse) -> SingleRerankingResponse:
        # Try to eat anything the user can throw at us

        if isinstance(raw_response, list):
            return { "documents": raw_response }

        if isinstance(raw_response, DSSLLMRerankingResponse):
            return raw_response._resp

        if isinstance(raw_response, dict):
            return raw_response

        raise Exception("Unrecognized response type (%s)" % type(raw_response))
